package com.lmspilot.integration.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="integration_adapters") public class IntegrationAdapterEntity{@Id private UUID id=UUID.randomUUID();@Column(nullable=false,unique=true,length=100)private String code="";@Column(nullable=false,length=180)private String name="";@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private AdapterType type=AdapterType.GENERIC_REST;@Column(nullable=false,length=1000)private String endpoint="";@Column(nullable=false,columnDefinition="text")private String mappingJson="{}";@Column(nullable=false,columnDefinition="text")private String secretReference="";@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private AdapterStatus status=AdapterStatus.DRAFT;private Instant lastTestedAt;@Column(columnDefinition="text")private String lastTestResult;@Column(nullable=false)private Instant updatedAt=Instant.now();@Version private long rowVersion;public IntegrationAdapterEntity(){}public UUID getId(){return id;}public String getCode(){return code;}public void setCode(String v){code=v;}public String getName(){return name;}public void setName(String v){name=v;}public AdapterType getType(){return type;}public void setType(AdapterType v){type=v;}public String getEndpoint(){return endpoint;}public void setEndpoint(String v){endpoint=v;}public String getMappingJson(){return mappingJson;}public void setMappingJson(String v){mappingJson=v;}public String getSecretReference(){return secretReference;}public void setSecretReference(String v){secretReference=v;}public AdapterStatus getStatus(){return status;}public void setStatus(AdapterStatus v){status=v;}public Instant getLastTestedAt(){return lastTestedAt;}public void setLastTestedAt(Instant v){lastTestedAt=v;}public String getLastTestResult(){return lastTestResult;}public void setLastTestResult(String v){lastTestResult=v;}public void setUpdatedAt(Instant v){updatedAt=v;}}
